---InitLevelRewardsInfo 初始化等级奖励信息
function GachaCoinQuestTitleInfo:InitLevelRewardsInfo()
    ---@type GachaCoinQuestLevelVo[]
    local allLevelInfo = GCQUtils.GetAllVo(AutoIds.IdSetting701):GetAll()

    local pivot = Vector2.New(0.5, 1)
    local paddingY = 5
    local topY = -102
    local level = nil
    local max = nil
    --local cellHeight = nil
    local rectTransfrom = nil

    for index, levelInfo in ipairs(allLevelInfo) do

        level = checkInt(levelInfo.id)
        max = checkInt(levelInfo.maxItemNum)
        
        local go = GameUtils.LoadBundleSync(GCQConstants.Path.LevelInfoPrefab, self.LevelInfoBg.gameObject)
        if not IsNull(go) then
            -- 刷新位置
            rectTransfrom = go:GetComponent(RectTransform_)
            rectTransfrom.pivot = pivot
            rectTransfrom.anchoredPosition = Vector2.New(
                0, topY - ((index - 1) * (rectTransfrom.sizeDelta.y + paddingY * 2))
            )
            -- 刷新内容
            local goScript = GetLuaBehaviour(go, GCQConstants.Path.LevelInfoScript)
            if not IsNull(goScript) and not IsNull(goScript.Env) then
                goScript.Env:RefreshView(index, level, max)
            end
            --if not cellHeight then
            --    cellHeight = rectTransfrom.rect.height
            --end
        end
        self.levelInfos[level] = go
        -- self.levelInfoLoaders[level] = loader

    end
    --printInfo("height_______>>"..self.LevelInfoBg.sizeDelta.y)
    --self.LevelInfoBg.sizeDelta.y = topY + max * (topY + paddingY + cellHeight)
    --printInfo(level.."---heightTarget_______>>"..math.abs(topY) + level * ( paddingY + cellHeight))
    --printInfo("height22_______>>"..self.LevelInfoBg.sizeDelta.y)


end


