function GachaCoinQuestTitleInfo:RefreshActiveStatus(questId)
    local questType = GCQUtils.GetGachaCoinQuestTypeById(questId)
    local isChallengeQuest = GCQConstants.Defines.QuestType.Challenge == questType
    KTool.SetActive(self.controller, not isChallengeQuest)
end


---RefreshTitleInfo 刷新标题板
---@param level integer @ 副本等级
---@param coinAmount integer @ 已获得的奖励数量
---@param coinGoodsId integer @ 奖励道具id
---@param countdown integer @ 倒计时 秒
function GachaCoinQuestTitleInfo:RefreshTitleInfo(level, coinAmount, coinGoodsId)
    -- 根据等级刷新当前假象实战奖励信息
    self:RefreshCurrentLevel(level)

    self:SetQuestLevel(level)
    -- 刷新获得的道具数量
    self:RefreshCoinInfo(level, coinAmount, coinGoodsId)
    -- 刷新倒计时
    --self:RefreshCountdown(countdown)
end

---RefreshCurrentLevel 根据等级刷新当前等级信息
---@param level integer @ 等级
function GachaCoinQuestTitleInfo:RefreshCurrentLevel(level)
    local scr = nil
    local preLevelNode = self:GetLevelInfoNodeByLevel(self:GetQuestLevel())
    if not IsNull(preLevelNode) then
        scr = GetLuaBehaviour(preLevelNode, GCQConstants.Path.LevelInfoScript)
        if not IsNull(scr) and not IsNull(scr.Env) then
            scr.Env:SetCurrent(false)
        end
    end

    local curLevelNode = self:GetLevelInfoNodeByLevel(level)
    if not IsNull(curLevelNode) then
        scr = GetLuaBehaviour(curLevelNode, GCQConstants.Path.LevelInfoScript)
        if not IsNull(scr) and not IsNull(scr.Env) then
            scr.Env:SetCurrent(true)
        end
    end
end

---RefreshCoinInfo 刷新获得的道具数量信息
---@param level integer @ 副本等级
---@param coinAmount integer @ 已获得的奖励数量
---@param coinGoodsId integer @ 奖励道具id
function GachaCoinQuestTitleInfo:RefreshCoinInfo(level, coinAmount, coinGoodsId)
    -- 刷新等级文字
    self.LevelLabel.text = GCQUtils.GetFormattedNumber(level, 2)

    -- 刷新获得的文字
    local coinMax = GCQUtils.GetGachaCoinMaxByLevel(level)
    local coinStr = string.format(
        '%d<size=24><color=#B1AEAE>/%d</color></size>',
        checkInt(coinAmount), coinMax
    )
    self.CoinAmount.text = coinStr
    self.CoinLabelConFitter:SetLayoutVertical()

    -- 刷新道具图标
    if not isNull(coinGoodsId) then
        -- TODO --
    end
end

-----RefreshCountdown 刷新倒计时
---@param countdown integer @ 倒计时 秒
function GachaCoinQuestTitleInfo:RefreshCountdown(countdown)
    local cdDescr = GCQUtils.GetCountdownDescrByCd(countdown)
    self.TimerLabel.text = cdDescr
end

---ShowLevelInfoNode 显示等级奖励信息
---@param show boolean @ 是否显示等级奖励信息
function GachaCoinQuestTitleInfo:ShowLevelInfoNode(show)
    if nil == show then
        show = not KTool.IsActive(self.LevelInfoBg.gameObject)
    end
    KTool.SetActive(self.LevelInfoBg.gameObject, show)
    KTool.SetActive(self.Cover.gameObject, show)
end


